<script setup>
import { computed, onMounted, reactive, ref, watch } from "vue";
import { Check, Download, Edit3, FileSpreadsheet, LoaderCircle, Plus, RefreshCw, Search, Trash2, Upload, X } from "lucide-vue-next";
import { api, download } from "../api/client";
import { useRoute, useRouter } from "vue-router";
import { useToastStore } from "../stores/toast";

const props = defineProps({
  role: { type: String, required: true },
  config: { type: Object, required: true },
  embedded: { type: Boolean, default: false },
});
const route = useRoute(); const router = useRouter();
const toast = useToastStore();
const items = ref([]); const options = reactive({ classrooms: [], teachers: [], students: [] }); const loading = ref(true); const saving = ref(false); const error = ref(""); const notice = ref(""); const editingId = ref(null); const query = ref(""); const importFile = ref(null); const importPreview = ref(null); const importing = ref(false); const form = reactive({}); const selectedClassroom = ref(null); const classroomLoading = ref(false);
const labels = { first_name: "名字", second_name: "中间名", last_name: "姓氏", surname: "姓氏", career_name: "教师称呼", email: "邮箱", phone_number: "电话号码", gender: "性别", password: "密码", name: "名称", teacher_id: "负责教师", admission_number: "学号", age: "年龄", description: "描述", classroom_id: "班级", student_id: "学生", title: "标题", date: "日期", status: "状态", source_type: "内容来源", body: "正文", recurrence: "频率", scheduled_at: "计划时间", send_time: "发送时间", weekday: "星期", stage: "阶段", level: "等级", subject: "学科", min_age: "最小年龄", max_age: "最大年龄" };
const endpoint = computed(() => props.config.endpoint); const isAdmin = computed(() => props.role === "admin"); const isClassroom = computed(() => endpoint.value.includes("classrooms")); const isApproval = computed(() => props.config.approval); const isCreateOnly = computed(() => Boolean(props.config.createOnly)); const isReadOnly = computed(() => props.config.readOnly || props.config.sessions); const filteredItems = computed(() => { const q = query.value.trim().toLowerCase(); if (!q) return items.value; return items.value.filter((item) => JSON.stringify(item).toLowerCase().includes(q)); });
const tableFields = computed(() => { const fields = props.config.fields || []; const compacted = fields.includes("first_name") ? fields.filter((field) => !["second_name", "surname"].includes(field)) : fields; return compacted.slice(0, 5); });
const visibleFields = computed(() => props.config.fields.filter((field) => field !== "password" || !editingId.value || props.role === "admin"));

function resetForm() { const fields = new Set(props.config.fields || []); Object.keys(form).forEach((field) => { if (!fields.has(field)) delete form[field]; }); props.config.fields.forEach((field) => { form[field] = field === "status" ? "draft" : field === "age" ? "3" : field === "student_id" ? route.query.student_id || localStorage.getItem("studentId") || "" : ""; }); editingId.value = null; }
function fullName(item) { return [item?.first_name, item?.second_name, item?.surname || item?.last_name].filter(Boolean).join(" "); }
function summary(item) { return item?.name || item?.title || fullName(item) || item?.student_name || item?.parent_name || `记录 #${item?.id || "-"}`; }
function formatValue(item, field) { if (field === "teacher_id") return item.teacher?.career_name || item.teacher?.first_name || item.teacher_id || "-"; if (field === "classroom_id") return item.classroom?.name || item.classroom_id || "-"; if (field === "student_id") return item.student?.first_name ? fullName(item.student) : item.student_id || "-"; if (field === "password") return "••••••"; return item[field] ?? "-"; }
function fieldType(field) { if (["description", "body"].includes(field)) return "textarea"; if (["age", "min_age", "max_age", "teacher_id", "classroom_id", "student_id", "weekday"].includes(field)) return "number"; if (["date", "scheduled_at", "send_time"].includes(field)) return field === "date" ? "date" : field === "send_time" ? "time" : "datetime-local"; return field === "email" ? "email" : field === "password" ? "password" : "text"; }
function optionsFor(field) { if (field === "teacher_id") return options.teachers; if (field === "classroom_id") return options.classrooms; if (field === "student_id") return options.students; return []; }
function optionLabel(field, item) { return field === "teacher_id" ? `${item.career_name || "教师"} · ${fullName(item)}` : field === "classroom_id" ? item.name : `${fullName(item)} · ${item.admission_number || item.id}`; }

async function load() { loading.value = true; error.value = ""; try { const data = await api.get(endpoint.value, props.role); items.value = Array.isArray(data) ? data : data?.data || data?.items || []; if (isAdmin.value && !isReadOnly.value) { if (isClassroom.value) options.teachers = await api.get("/admin/teachers", "admin"); if (endpoint.value.includes("students")) options.classrooms = await api.get("/admin/classrooms", "admin"); if (endpoint.value.includes("disciplines")) options.students = await api.get("/admin/students", "admin"); } if (!isAdmin.value && (endpoint.value === "/students" || endpoint.value.includes("disciplines") || endpoint.value.includes("attendances"))) options.students = await api.get("/students", "teacher"); } catch (cause) { error.value = cause.message || "数据加载失败"; } finally { loading.value = false; } }
onMounted(() => { resetForm(); load(); }); watch(() => [endpoint.value, props.config.createOnly, route.fullPath], () => { resetForm(); load(); });

function startEdit(item) { editingId.value = item.id; props.config.fields.forEach((field) => { form[field] = field === "teacher_id" ? item.teacher?.id || item.teacher_id || "" : field === "classroom_id" ? item.classroom?.id || item.classroom_id || "" : field === "student_id" ? item.student?.id || item.student_id || "" : item[field] ?? ""; }); window.scrollTo({ top: 0, behavior: "smooth" }); }
async function save() { saving.value = true; notice.value = ""; const wasEditing = Boolean(editingId.value); try { const payload = { ...form }; Object.keys(payload).forEach((key) => { if (payload[key] === "") delete payload[key]; }); await (wasEditing ? api.patch(`${endpoint.value}/${editingId.value}`, payload, props.role) : api.post(endpoint.value, payload, props.role)); notice.value = wasEditing ? "记录已更新" : "记录已创建"; toast.success(notice.value); if (isCreateOnly.value && !wasEditing) { localStorage.removeItem("studentId"); await router.push(props.config.returnTo || (endpoint.value.includes("disciplines") ? "/dashboard/discipline" : "/dashboard/kids_list")); return; } resetForm(); await load(); } catch (cause) { error.value = cause.message || "保存失败"; toast.error(error.value); } finally { saving.value = false; } }
async function remove(item) { if (!window.confirm(`确认删除 ${fullName(item) || item.title || item.name || `记录 #${item.id}`}？`)) return; try { await api.delete(`${endpoint.value}/${item.id}`, props.role); notice.value = "记录已删除"; await load(); } catch (cause) { error.value = cause.message || "删除失败"; } }
async function approve(item, status) { try { await api.patch(`/admin/parent_students/${item.id}`, { status }, "admin"); notice.value = status === "approved" ? "绑定申请已通过" : "绑定申请已拒绝"; await load(); } catch (cause) { error.value = cause.message || "审批失败"; } }
async function removeApproval(item) { if (!window.confirm(`确认删除 ${item.parent_name || item.parent?.first_name || "这条绑定申请"}？`)) return; try { await api.delete(`/admin/parent_students/${item.id}`, "admin"); notice.value = "绑定记录已删除"; await load(); } catch (cause) { error.value = cause.message || "删除失败"; } }
async function inspectClassroom(item) { classroomLoading.value = true; error.value = ""; try { selectedClassroom.value = await api.get(`/classrooms/${item.id}`, props.role); } catch (cause) { error.value = cause.message || "学生列表加载失败"; } finally { classroomLoading.value = false; } }
function selectFile(event) { importFile.value = event.target.files?.[0] || null; importPreview.value = null; }
async function previewImport() { if (!importFile.value) return; const data = new FormData(); data.append("file", importFile.value); importing.value = true; try { importPreview.value = await api.form("/admin/classroom_imports/preview", data, "admin"); } catch (cause) { error.value = cause.message || "解析失败"; } finally { importing.value = false; } }
async function confirmImport() { if (!importFile.value || !importPreview.value?.valid) return; const data = new FormData(); data.append("file", importFile.value); importing.value = true; try { await api.form("/admin/classroom_imports", data, "admin"); notice.value = "班级和学生已导入"; importFile.value = null; importPreview.value = null; await load(); } catch (cause) { error.value = cause.message || "导入失败"; } finally { importing.value = false; } }
async function downloadTemplate(format) { try { await download(`/admin/classroom_imports/template?format=${format}`, `班级导入模板.${format}`, "admin"); } catch (cause) { error.value = cause.message || "下载失败"; } }
</script>

<template>
  <div><div v-if="!embedded" class="page-heading"><div><span class="mono-label">{{ role.toUpperCase() }} / {{ config.title.toUpperCase() }}</span><h1>{{ config.title }}</h1><p>{{ isApproval ? '审阅家长与孩子的绑定申请，确保数据访问经过授权。' : isCreateOnly ? '填写表单后返回列表，数据会自动归入当前班级。' : isReadOnly ? '数据只读观察视图，所有记录均来自实时 API。' : '用统一的操作面板维护园所数据，让日常管理更顺手。' }}</p></div><button class="button button-dark" type="button" @click="load"><RefreshCw :size="15" />刷新</button></div>
    <div v-if="notice" class="notice" style="margin-bottom:14px">{{ notice }} <button class="icon-button" style="float:right; width:22px; height:22px" title="关闭" @click="notice=''"><X :size="13" /></button></div><div v-if="error" class="notice error" style="margin-bottom:14px">{{ error }}</div>
    <section v-if="!isReadOnly && !isApproval" class="surface surface-pad" style="margin-bottom:18px"><div class="surface-title"><h2>{{ editingId ? '编辑记录' : '新增记录' }}</h2><span>DATA INPUT</span></div><form class="form-grid" @submit.prevent="save"><div v-for="field in visibleFields" :key="field" class="field" :class="{ wide: ['description','body'].includes(field) }"><label :for="`field-${field}`">{{ labels[field] || field }}</label><textarea v-if="fieldType(field)==='textarea'" :id="`field-${field}`" v-model="form[field]" :placeholder="`请输入${labels[field] || field}`" :required="isCreateOnly" /><select v-else-if="['teacher_id','classroom_id','student_id'].includes(field)" :id="`field-${field}`" v-model="form[field]" :required="isCreateOnly"><option value="">请选择{{ labels[field] }}</option><option v-for="option in optionsFor(field)" :key="option.id" :value="option.id">{{ optionLabel(field, option) }}</option></select><input v-else :id="`field-${field}`" v-model="form[field]" :type="fieldType(field)" :placeholder="`请输入${labels[field] || field}`" :required="isCreateOnly" /></div><div class="form-actions"><button v-if="editingId" class="button button-ghost" type="button" @click="resetForm"><X :size="15" />取消编辑</button><button class="button button-primary" type="submit" :disabled="saving"><LoaderCircle v-if="saving" :size="15" class="spin" />{{ saving ? '保存中...' : editingId ? '保存修改' : '创建记录' }}</button></div></form></section>
    <section v-if="isClassroom && isAdmin" class="surface surface-pad" style="margin-bottom:18px"><div class="surface-title"><h2><FileSpreadsheet :size="17" style="vertical-align:-3px; margin-right:7px" />批量导入班级与学生</h2><span>XLSX / CSV</span></div><div class="toolbar"><div class="filter-row"><button class="button button-light" type="button" @click="downloadTemplate('xlsx')"><Download :size="14" />下载 XLSX 模板</button><button class="button button-light" type="button" @click="downloadTemplate('csv')"><Download :size="14" />下载 CSV 模板</button></div><div class="filter-row"><input type="file" accept=".xlsx,.csv" @change="selectFile" /><button class="button button-dark" type="button" :disabled="importing" @click="previewImport"><Upload :size="14" />解析文件</button><button v-if="importPreview?.valid" class="button button-primary" type="button" :disabled="importing" @click="confirmImport"><Check :size="14" />确认导入</button></div></div><div v-if="importPreview" class="notice" style="margin-top:12px">{{ importPreview.valid ? `解析成功：${importPreview.students?.length || 0} 名学生` : `发现 ${importPreview.errors?.length || 0} 个问题，请修正后重试` }}</div></section>
<section v-if="!isCreateOnly" class="surface"><div class="toolbar" style="padding:16px 18px 0"><div class="filter-row"><div style="position:relative"><Search :size="15" style="position:absolute; left:11px; top:12px; color:#7894a3" /><input v-model="query" class="filter-input" style="padding-left:34px" :placeholder="`搜索${config.title}`" /></div><span class="mono-label" style="align-self:center">{{ filteredItems.length }} 条记录</span></div><div class="row-actions"><button v-if="embedded" class="button button-dark" type="button" @click="load"><RefreshCw :size="15" />刷新</button><button v-if="!isReadOnly && !isApproval" class="button button-primary" type="button" @click="resetForm"><Plus :size="15" />新建</button></div></div><div v-if="loading" style="padding:18px; display:grid; gap:8px"><div v-for="i in 4" :key="i" class="skeleton" /></div><div v-else-if="!filteredItems.length" class="empty-state"><strong>暂无数据</strong><span>当前筛选条件下没有可展示的记录。</span></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th v-if="config.sessions">会话</th><th v-else-if="isApproval">申请人 / 孩子</th><th v-else-if="!tableFields.length">记录</th><th v-for="field in (config.sessions || isApproval ? [] : tableFields)" :key="field">{{ labels[field] || field }}</th><th>操作</th></tr></thead><tbody><tr v-for="item in filteredItems" :key="item.id"><td v-if="config.sessions"><strong>{{ item.title || '儿童陪伴对话' }}</strong><small style="display:block; margin-top:4px; color:#7894a3">{{ item.student_name || item.student?.first_name || '-' }}</small></td><td v-else-if="isApproval"><strong>{{ item.parent_name || item.parent?.first_name || '-' }}</strong><small style="display:block; margin-top:4px; color:#7894a3">{{ item.student_name || item.student?.first_name || '-' }} · {{ item.status }}</small></td><td v-else-if="!tableFields.length"><strong>{{ summary(item) }}</strong><small style="display:block; margin-top:4px; color:#7894a3">{{ item.teacher?.career_name || item.email || item.phone_number || item.status || '' }}</small></td><td v-for="field in tableFields" v-else :key="field">{{ field === 'first_name' ? fullName(item) : formatValue(item, field) }}</td><td><div class="row-actions"><template v-if="role === 'teacher' && endpoint === '/students'"><RouterLink class="row-action" :to="`/dashboard/kids_list/${item.id}/growth`">成长记录</RouterLink><RouterLink class="row-action" :to="`/dashboard/kids_list/${item.id}`">详情</RouterLink></template><template v-if="isApproval"><button class="row-action" type="button" @click="approve(item,'approved')">通过</button><button class="row-action" style="color:#ad5148" type="button" @click="approve(item,'rejected')">拒绝</button><button class="row-action" style="color:#ad5148" type="button" title="删除绑定记录" @click="removeApproval(item)"><Trash2 :size="13" /></button></template><template v-else-if="isClassroom && !isAdmin"><button class="row-action" type="button" @click="inspectClassroom(item)">查看学生</button></template><template v-else-if="!isReadOnly"><button class="row-action" type="button" title="编辑" @click="startEdit(item)"><Edit3 :size="13" /></button><button class="row-action" style="color:#ad5148" type="button" title="删除" @click="remove(item)"><Trash2 :size="13" /></button></template><span v-else class="status neutral">只读</span></div></td></tr></tbody></table></div></section>
<section v-if="selectedClassroom" class="surface surface-pad" style="margin-top:18px"><div class="surface-title"><h2>{{ selectedClassroom.name }} · 学生名单</h2><button class="icon-button" type="button" title="关闭" @click="selectedClassroom=null"><X :size="14" /></button></div><div v-if="classroomLoading" class="empty-state"><LoaderCircle class="spin" :size="25" /></div><div v-else-if="!selectedClassroom.students?.length" class="empty-state">该班级暂无学生。</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>学号</th><th>姓名</th><th>年龄</th><th>描述</th></tr></thead><tbody><tr v-for="student in selectedClassroom.students" :key="student.id"><td>{{ student.admission_number || '-' }}</td><td>{{ fullName(student) }}</td><td>{{ student.age || '-' }}</td><td>{{ student.description || '-' }}</td></tr></tbody></table></div></section>
  </div>
</template>

<style scoped>.spin { animation: spin 1s linear infinite; } @keyframes spin { to { transform:rotate(360deg); } }</style>
